---将prices转为需要的格式
function GroceryHomeDojo:ConvertPrices(data)
    if not data.prices then return end
    
    local prices = {}
    for k, v in pairs(checkTable(data.prices)) do
        local tmp = {}
        tmp.current = v.current
        tmp.original = v.original
        tmp.currency = tonumber(k)
        table.insert(prices, tmp)
    end
    data.prices = prices
end

